{"command": "python3 <<'PY' 2>&1 | head -n 100
import subprocess, os
def run(env_extra):
    e=os.environ.copy()
    for k in ["IGREP_EDITOR","VISUAL","EDITOR","IGREP_CUSTOM_EDITOR"]:
        e.pop(k, None)
    e.update(env_extra)
    p=subprocess.run(["/workspace/executable","pattern"], capture_output=True, text=True, env=e, cwd="/tmp")
    return p.stderr.strip()
from collections import Counter
for env in [{"VISUAL":"vim"}, {"EDITOR":"vim"}, {"IGREP_EDITOR":"vim"}, {}]:
    c=Counter(run(env) for _ in range(10))
    print(env, c)
PY
"}

