use anyhow::{Context, Result, anyhow, bail};
use std::path::{Path, PathBuf};
use std::collections::{HashSet, HashMap};

const EDITORS: &[&str] = &["vim","neovim","nvim","nano","code","vscode","code-insiders","emacs","emacsclient","hx","helix","subl","sublime-text","micro","intellij","goland","pycharm","less","fresh"];

fn main() -> Result<()> {
    let m = Command::new("igrep")
        .version("1.3.0")
        .about("Interactive Grep")
        .arg(Arg::new("PATTERN").help("Regular expression used for searching").required(true).conflicts_with("type-list"))
        .arg(Arg::new("PATHS").help("Files or directories to search. Directories are searched recursively. If not specified, searching starts from current directory").num_args(1..))
        .arg(Arg::new("editor").long("editor").value_name("EDITOR").help("Text editor used to open selected match").value_parser(EDITORS).conflicts_with("custom-command"))
        .arg(Arg::new("custom-command").long("custom-command").value_name("CUSTOM_COMMAND").help("Custom command used to open selected match. Must contain {file_name} and {line_number} tokens").env("IGREP_CUSTOM_EDITOR").conflicts_with("editor"))
        .arg(Arg::new("theme").long("theme").value_name("THEME").help("UI color theme").default_value("dark").value_parser(["light","dark"]))
        .arg(Arg::new("ignore-case").short('i').long("ignore-case").help("Searches case insensitively").action(ArgAction::SetTrue))
        .arg(Arg::new("smart-case").short('S').long("smart-case").help("Searches case insensitively if the pattern is all lowercase. Search case sensitively otherwise").action(ArgAction::SetTrue))
        .arg(Arg::new("hidden").short('.').long("hidden").help("Search hidden files and directories. By default, hidden files and directories are skipped").action(ArgAction::SetTrue))
        .arg(Arg::new("follow").short('L').long("follow").help("Follow symbolic links while traversing directories").action(ArgAction::SetTrue))
        .arg(Arg::new("word-regexp").short('w').long("word-regexp").help("Only show matches surrounded by word boundaries").action(ArgAction::SetTrue))
        .arg(Arg::new("fixed-strings").short('F').long("fixed-strings").help("Exact matches with no regex. Useful when searching for a string full of delimiters").action(ArgAction::SetTrue))
        .arg(Arg::new("multiline").short('U').long("multiline").help("Search with pattern contains newline character ('\\n')").action(ArgAction::SetTrue))
        .arg(Arg::new("glob").short('g').long("glob").value_name("GLOB").help("Include files and directories for searching that match the given glob. Multiple globs may be provided").action(ArgAction::Append))
        .arg(Arg::new("type-list").long("type-list").help("Show all supported file types and their corresponding globs").action(ArgAction::SetTrue).required(true).conflicts_with("PATTERN"))
        .arg(Arg::new("type").short('t').long("type").value_name("TYPE_MATCHING").help("Only search files matching TYPE. Multiple types may be provided").action(ArgAction::Append))
        .arg(Arg::new("type-not").short('T').long("type-not").value_name("TYPE_NOT").help("Do not search files matching TYPE-NOT. Multiple types-not may be provided").action(ArgAction::Append))
        .arg(Arg::new("context-viewer").long("context-viewer").value_name("CONTEXT_VIEWER").help("Context viewer position at startup").default_value("none").value_parser(["none","vertical","horizontal"]))
        .arg(Arg::new("sort").long("sort").value_name("SORT_BY").help("Sort results, see ripgrep for details").value_parser(["path","modified","created","accessed"]))
        .arg(Arg::new("sortr").long("sortr").value_name("SORT_BY_REVERSE").help("Sort results reverse, see ripgrep for details").value_parser(["path","modified","created","accessed"]))
        .get_matches();
    if m.get_flag("type-list") {
        print!(include_str!("../typelist.txt"));
        return Ok(());
    }
    let pattern: String = m.get_one::<String>("PATTERN").unwrap().clone();
    let paths: Vec<String> = m.get_many::<String>("PATHS").map(|v| v.cloned().collect()).unwrap_or_default();
    let theme: String = m.get_one::<String>("theme").unwrap().clone();
    let _theme = theme;
    let ignore_case = m.get_flag("ignore-case");
    let smart_case = m.get_flag("smart-case");
    let hidden = m.get_flag("hidden");
    let follow = m.get_flag("follow");
    let word = m.get_flag("word-regexp");
    let fixed = m.get_flag("fixed-strings");
    let multiline = m.get_flag("multiline");
    let globs: Vec<String> = m.get_many::<String>("glob").map(|v| v.cloned().collect()).unwrap_or_default();
    let types: Vec<String> = m.get_many::<String>("type").map(|v| v.cloned().collect()).unwrap_or_default();
    let types_not: Vec<String> = m.get_many::<String>("type-not").map(|v| v.cloned().collect()).unwrap_or_default();
    let context_viewer: String = m.get_one::<String>("context-viewer").unwrap().clone();
    let sort: Option<String> = m.get_one::<String>("sort").cloned();
    let sortr: Option<String> = m.get_one::<String>("sortr").cloned();
    // custom command validation
    let custom_cmd: Option<String> = m.get_one::<String>("custom-command").cloned();
    if let Some(ref cmd) = custom_cmd {
        validate_custom_command(cmd).with_context(|| format!("Incorrect editor command: '{}'", cmd))?;
    }
    // editor validation (only if no custom)
    let editor_cli: Option<String> = m.get_one::<String>("editor").cloned();
    let editor_choice: Option<String> = if custom_cmd.is_some() {
        None
    } else if let Some(e) = editor_cli {
        Some(e)
    } else {
        // check envs in order
        let mut chosen: Option<String> = None;
        for var in &["IGREP_EDITOR", "VISUAL", "EDITOR"] {
            if let Ok(val) = std::env::var(var) {
                // validate
                if !EDITORS.contains(&val.as_str()) {
                    let msg = format!("\"{}\" read from ${}, possible variants: [{}]", val, var, EDITORS.join(", "));
                    let inner = anyhow!("invalid variant: {}", val);
                    return Err(inner.context(msg).into());
                    // Actually need Error: outer + Caused by inner. Using anyhow context will produce that.
                } else {
                    chosen = Some(val);
                    break;
                }
            }
        }
        chosen
    };
    // spawn search thread (for panic behavior on invalid regex)
    let pattern_c = pattern.clone();
    let paths_c = paths.clone();
    let globs_c = globs.clone();
    let types_c = types.clone();
    let types_not_c = types_not.clone();
    let handle = std::thread::spawn(move || {
        let re = ig::searcher::build_regex(&pattern_c, ignore_case, smart_case, word, fixed, multiline);
        run_search(&re, &paths_c, hidden, follow, &globs_c, &types_c, &types_not_c, sort.as_deref(), sortr.as_deref(), multiline)
    });
    // check terminal size (fails with EAGAIN when not tty, matching original)
    // small delay to let search thread panic first (so panic prints before EAGAIN)
    std::thread::sleep(std::time::Duration::from_millis(100));
    // This call fails when stdout is not a tty, with EAGAIN
    let _ = crossterm::terminal::size()?;
    // wait for search results; if thread panicked, exit 0 (as original does with tty)
    let search_results = match handle.join() {
        Ok(r) => r,
        Err(_) => {
            // search thread panicked (invalid regex); with tty, original exits 0 after showing panic
            // panic message already printed by runtime; just exit 0
            return Ok(());
        }
    };
    // run TUI
    run_tui(pattern, paths, search_results, editor_choice, custom_cmd, context_viewer, sort, sortr)?;
    Ok(())
}

fn validate_custom_command(cmd: &str) -> Result<()> {
    // must contain space
    if !cmd.contains(' ') {
        bail!("Expected program and its arguments");
    }
    let idx = cmd.find(' ').unwrap();
    let args_part = &cmd[idx+1..];
    let file_count = args_part.matches("{file_name}").count();
    if file_count != 1 {
        bail!("Expected one occurrence of '{{file_name}}'.");
    }
    let line_count = args_part.matches("{line_number}").count();
    if line_count != 1 {
        bail!("Expected one occurrence of '{{line_number}}'.");
    }
    Ok(())
}
