fn make_display_path(path: &Path, _walk_root: &PathBuf) -> String {
    // Try to make relative to current dir
    if let Ok(cwd) = std::env::current_dir() {
        if let Ok(rel) = path.strip_prefix(&cwd) {
            let s = rel.to_string_lossy().to_string();
            if s.is_empty() {
                return path.to_string_lossy().to_string();
            }
            // Remove leading ./ if present?
            let s = s.trim_start_matches("./").to_string();
            return s;
        }
    }
    // Fallback: if path starts with ./, strip?
    let s = path.to_string_lossy().to_string();
    if s.starts_with("./") {
        return s[2..].to_string();
    }
    s
}

fn search_single_file(re: &regex::Regex, path: &Path, display: &str) -> Option<FileMatches> {
    // Read file, skip binary (null bytes) and errors
    let content = match std::fs::read(path) {
        Ok(b) => b,
        Err(_) => return None,
    };
    // Binary check: if contains null byte in first 8000 bytes, skip
    let check_len = std::cmp::min(content.len(), 8000);
    if content[..check_len].contains(&0) {
        return None;
    }
    let text = match String::from_utf8(content) {
        Ok(s) => s,
        Err(_) => return None,
    };
    let mut matches = Vec::new();
    for (idx, line) in text.lines().enumerate() {
        if re.is_match(line) {
            matches.push((idx+1, line.to_string()));
        }
    }
    // Get metadata for sorting
    let (modified, created, accessed) = match std::fs::metadata(path) {
        Ok(md) => (md.modified().ok(), md.created().ok(), md.accessed().ok()),
        Err(_) => (None, None, None),
    };
    Some(FileMatches { path: path.to_string_lossy().to_string(), display_path: display.to_string(), matches, modified, created, accessed })
}

fn apply_sort(results: &mut Vec<FileMatches>, sort: Option<&str>, sortr: Option<&str>) {
    if let Some(s) = sort {
        match s {
            "path" => results.sort_by(|a,b| a.display_path.cmp(&b.display_path)),
            "modified" => results.sort_by(|a,b| a.modified.cmp(&b.modified)),
            "created" => results.sort_by(|a,b| a.created.cmp(&b.created)),
            "accessed" => results.sort_by(|a,b| a.accessed.cmp(&b.accessed)),
            _ => {}
        }
    } else if let Some(s) = sortr {
        match s {
            "path" => results.sort_by(|a,b| b.display_path.cmp(&a.display_path)),
            "modified" => results.sort_by(|a,b| b.modified.cmp(&a.modified)),
            "created" => results.sort_by(|a,b| b.created.cmp(&a.created)),
            "accessed" => results.sort_by(|a,b| b.accessed.cmp(&a.accessed)),
            _ => {}
        }
    }
}

