#[derive(Clone, Debug)]
struct FileMatches {
    path: String,
    display_path: String,
    matches: Vec<(usize, String)>,
    modified: Option<std::time::SystemTime>,
    created: Option<std::time::SystemTime>,
    accessed: Option<std::time::SystemTime>,
}

fn run_search(re: &regex::Regex, paths: &[String], hidden: bool, follow: bool, globs: &[String], types: &[String], types_not: &[String], sort: Option<&str>, sortr: Option<&str>, _multiline: bool) -> Vec<FileMatches> {
    use ignore::WalkBuilder;
    use globset::{GlobBuilder, GlobSetBuilder};
    use std::collections::HashMap;
    let typelist_str = include_str!("../typelist.txt");
    let mut type_to_globs: HashMap<String, Vec<String>> = HashMap::new();
    for line in typelist_str.lines() {
        if let Some(idx) = line.find(':') {
            let name = line[..idx].trim().to_string();
            let globs_str = line[idx+1..].trim();
            let globs_vec: Vec<String> = globs_str.split(", ").map(|s| s.trim().to_string()).collect();
            type_to_globs.insert(name, globs_vec);
        }
    }
    let mut glob_builder = GlobSetBuilder::new();
    for g in globs {
        if let Ok(glob) = GlobBuilder::new(g).literal_separator(true).build() {
            glob_builder.add(glob);
        }
    }
    let glob_set = glob_builder.build().ok();
    let mut type_globs: Vec<String> = Vec::new();
    for t in types {
        if let Some(v) = type_to_globs.get(t) {
            type_globs.extend(v.clone());
        } else {
            type_globs.push(format!("__impossible_{}__", t));
        }
    }
    let mut type_not_globs: Vec<String> = Vec::new();
    for t in types_not {
        if let Some(v) = type_to_globs.get(t) {
            type_not_globs.extend(v.clone());
        }
    }
    let mut type_builder = GlobSetBuilder::new();
    for g in &type_globs {
        if let Ok(glob) = GlobBuilder::new(g).literal_separator(true).build() {
            type_builder.add(glob);
        }
    }
    let type_set = if type_globs.is_empty() { None } else { type_builder.build().ok() };
    let mut type_not_builder = GlobSetBuilder::new();
    for g in &type_not_globs {
        if let Ok(glob) = GlobBuilder::new(g).literal_separator(true).build() {
            type_not_builder.add(glob);
        }
    }
    let type_not_set = if type_not_globs.is_empty() { None } else { type_not_builder.build().ok() };
    let search_paths: Vec<String> = if paths.is_empty() { vec![".".to_string()] } else { paths.to_vec() };
    let mut explicit_files: Vec<std::path::PathBuf> = Vec::new();
    let mut walk_paths: Vec<std::path::PathBuf> = Vec::new();
    for p in &search_paths {
        let pb = std::path::PathBuf::from(p);
        // Check if path exists as file (follow symlink for is_file)
        if pb.is_file() {
            explicit_files.push(pb);
        } else if pb.is_dir() {
            walk_paths.push(pb);
        } else {
            // Check symlink metadata: if symlink, treat as file (explicit)
            if std::fs::symlink_metadata(&pb).is_ok() {
                // It's a symlink (maybe broken? or to file/dir)
                // If it points to dir (via is_dir which follows), already handled as dir above? Actually is_dir follows, so symlink to dir would be is_dir true.
                // So remaining symlinks are to files (or broken). Treat as explicit file.
                explicit_files.push(pb);
            } else {
                // nonexistent: push to walk (will yield nothing, but keeps behavior)
                walk_paths.push(pb);
            }
        }
    }
    let should_include = |path: &std::path::Path| -> bool {
        if let Some(ref set) = glob_set {
            let matched = set.is_match(path) || path.file_name().map(|n| set.is_match(n)).unwrap_or(false);
            if !matched { return false; }
        }
        if let Some(ref set) = type_set {
            let fname = path.file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or_default();
            let matched = set.is_match(&fname) || set.is_match(path);
            if !matched { return false; }
        }
        if let Some(ref set) = type_not_set {
            let fname = path.file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or_default();
            if set.is_match(&fname) || set.is_match(path) { return false; }
        }
        true
    };
    let mut results: Vec<FileMatches> = Vec::new();
    for f in explicit_files {
        let display = f.to_string_lossy().to_string();
        // For explicit, display should be as given? Original shows "b.txt" for "b.txt", absolute for absolute.
        // We'll use as given, but normalize "./" prefix?
        let mut disp = display.clone();
        if disp.starts_with("./") { disp = disp[2..].to_string(); }
        if let Some(fm) = search_single_file(&re, &f, &disp) {
            if !fm.matches.is_empty() { results.push(fm); }
        }
    }
    for wp in walk_paths {
        let mut builder = WalkBuilder::new(&wp);
        builder.hidden(!hidden);
        builder.follow_links(follow);
        builder.git_ignore(true);
        builder.parents(true);
        builder.ignore(true);
        builder.git_global(true);
        builder.git_exclude(true);
        let walker = builder.build();
        for entry in walker {
            let entry = match entry { Ok(e) => e, Err(_) => continue };
            let path = entry.path();
            if entry.file_type().map(|ft| ft.is_dir()).unwrap_or(false) { continue; }
            if !should_include(path) { continue; }
            let display = make_display_path(path, &wp);
            if let Some(fm) = search_single_file(&re, path, &display) {
                if !fm.matches.is_empty() { results.push(fm); }
            }
        }
    }
    apply_sort(&mut results, sort, sortr);
    results
}

fn make_display_path(path: &std::path::Path, _walk_root: &std::path::PathBuf) -> String {
    if let Ok(cwd) = std::env::current_dir() {
        if let Ok(rel) = path.strip_prefix(&cwd) {
            let s = rel.to_string_lossy().to_string();
            if s.is_empty() { return path.to_string_lossy().to_string(); }
            let s = s.trim_start_matches("./").to_string();
            return s;
        }
    }
    let s = path.to_string_lossy().to_string();
    if s.starts_with("./") { return s[2..].to_string(); }
    s
}

fn search_single_file(re: &regex::Regex, path: &std::path::Path, display: &str) -> Option<FileMatches> {
    let content = match std::fs::read(path) { Ok(b) => b, Err(_) => return None };
    let check_len = std::cmp::min(content.len(), 8000);
    if content[..check_len].contains(&0) { return None; }
    let text = match String::from_utf8(content) { Ok(s) => s, Err(_) => return None };
    let mut matches = Vec::new();
    for (idx, line) in text.lines().enumerate() {
        if re.is_match(line) { matches.push((idx+1, line.to_string())); }
    }
    let (modified, created, accessed) = match std::fs::metadata(path) {
        Ok(md) => (md.modified().ok(), md.created().ok(), md.accessed().ok()),
        Err(_) => (None, None, None),
    };
    Some(FileMatches { path: path.to_string_lossy().to_string(), display_path: display.to_string(), matches, modified, created, accessed })
}

fn apply_sort(results: &mut Vec<FileMatches>, sort: Option<&str>, sortr: Option<&str>) {
    if let Some(s) = sort {
        match s {
            "path" => results.sort_by(|a,b| a.display_path.cmp(&b.display_path)),
            "modified" => results.sort_by(|a,b| a.modified.cmp(&b.modified)),
            "created" => results.sort_by(|a,b| a.created.cmp(&b.created)),
            "accessed" => results.sort_by(|a,b| a.accessed.cmp(&b.accessed)),
            _ => {}
        }
    } else if let Some(s) = sortr {
        match s {
            "path" => results.sort_by(|a,b| b.display_path.cmp(&a.display_path)),
            "modified" => results.sort_by(|a,b| b.modified.cmp(&a.modified)),
            "created" => results.sort_by(|a,b| b.created.cmp(&a.created)),
            "accessed" => results.sort_by(|a,b| b.accessed.cmp(&a.accessed)),
            _ => {}
        }
    }
}
