use std::collections::HashSet;
use std::collections::HashMap;

#[derive(Clone, PartialEq)]
enum ViewerMode { None, Vertical, Horizontal }

fn run_tui(initial_pattern: String, _paths: Vec<String>, initial_results: Vec<FileMatches>, editor_choice: Option<String>, custom_cmd: Option<String>, context_initial: String, _sort_cli: Option<String>, _sortr_cli: Option<String>) -> anyhow::Result<()> {
