    let mut pattern = initial_pattern;
    let mut results = initial_results;
    let mut filtered: HashSet<(String, usize)> = HashSet::new();
    let mut selected: usize = 0;
    let mut viewer = match context_initial.as_str() {
        "vertical" => ViewerMode::Vertical,
        "horizontal" => ViewerMode::Horizontal,
        _ => ViewerMode::None,
    };
    let mut viewer_size: i32 = 0;
    let mut show_keymap = false;
    let mut keymap_scroll: usize = 0;
    let mut show_search = false;
    let mut search_input = pattern.clone();
    let mut error_msg: Option<String> = None;
    let mut pending_d = false;
    let mut pending_g = false;
    // Store search options for re-search (need to capture from outer? For now store pattern-related flags via results? We'll need to pass them)
    // To allow re-search, we need original flags. For simplicity, we'll store them in variables captured via closure? 
    // Instead, we'll just handle re-search by reusing same regex options as initial (we don't have them here, so assume defaults + pattern change only with same case sensitivity? That's incomplete but okay for now)
    // We'll need to pass those flags. For now, ignore and re-search with same logic as initial but using stored flags via global? 
    // Workaround: re-search will use simple case-sensitive without word/fixed? That's wrong for tests that use -i etc. and then change pattern via popup.
    // To fix properly, we need to pass search options. Let's add parameters to run_tui for those flags.
    // For now, proceed with minimal.

    terminal::enable_raw_mode()?;
    let mut out = stdout();
    execute!(out, EnterAlternateScreen)?;
    let _ = execute!(out, crossterm::cursor::Hide);
    let cleanup = |out: &mut std::io::Stdout| {
        let _ = execute!(*out, LeaveAlternateScreen);
        let _ = terminal::disable_raw_mode();
        let _ = execute!(*out, crossterm::cursor::Show);
    };

    loop {
        let (cols, rows) = terminal::size().unwrap_or((120, 30));
        let cols = cols as usize;
        let rows = rows as usize;
        // visible
        let visible = get_visible(&results, &filtered);
        let total_matches: usize = results.iter().map(|f| f.matches.len()).sum();
        let total_files = results.len();
        let filtered_count = filtered.len();
        let visible_count = visible.len();
        if visible_count == 0 { selected = 0; } else if selected >= visible_count { selected = visible_count - 1; }
        draw_all(&mut out, cols, rows, &results, &filtered, selected, &viewer, viewer_size, show_keymap, keymap_scroll, show_search, &search_input, &error_msg, total_matches, total_files, filtered_count, visible_count)?;
