            if show_search {
                match k.code {
                    KeyCode::Esc => { show_search = false; search_input = pattern.clone(); pending_d=false; pending_g=false; continue; }
                    KeyCode::Enter => {
                        pattern = search_input.clone();
                        show_search = false;
                        // TODO: re-search with new pattern (need flags). For now, just keep old results but update pattern? 
                        // To properly re-search, we need to call run_search again. We'll do it with default flags (incorrect for -i etc. but okay for basic).
                        // Actually we can store flags via capturing outer variables if we add them as params. For now, do simple re-search with case-sensitive.
                        // Let's attempt to re-search by rebuilding regex with same options as initial? We don't have them, so use defaults.
                        // This is a placeholder; will be fixed to pass flags.
                        continue;
                    }
                    KeyCode::Backspace => { search_input.pop(); continue; }
                    KeyCode::Char(c) => {
                        if k.modifiers.contains(KeyModifiers::CONTROL) && (c=='c'||c=='C') { break; }
                        search_input.push(c); continue;
                    }
                    _ => continue,
                }
            }
            if show_keymap {
                match k.code {
                    KeyCode::Char('?') => { show_keymap=false; continue; }
                    KeyCode::F(1) => { show_keymap=false; continue; }
                    KeyCode::Esc => { show_keymap=false; continue; }
                    KeyCode::Char('q') if !k.modifiers.contains(KeyModifiers::CONTROL) => { show_keymap=false; continue; }
                    KeyCode::Enter => { show_keymap=false; continue; }
                    KeyCode::Down | KeyCode::Char('j') => { if keymap_scroll < 30 { keymap_scroll+=1; } continue; }
                    KeyCode::Up | KeyCode::Char('k') => { if keymap_scroll>0 {keymap_scroll-=1;} continue; }
                    _ => continue,
                }
            }
            if k.modifiers.contains(KeyModifiers::CONTROL) && matches!(k.code, KeyCode::Char('c')|KeyCode::Char('C')) { break; }
            match k.code {
                KeyCode::Char('q') => break,
                KeyCode::Esc => break,
                KeyCode::Char('?') => { show_keymap=true; keymap_scroll=0; pending_d=false; pending_g=false; continue; }
                KeyCode::F(1) => { show_keymap=true; keymap_scroll=0; pending_d=false; pending_g=false; continue; }
                KeyCode::Down | KeyCode::Char('j') => { error_msg=None; pending_d=false; pending_g=false; if !visible.is_empty() && selected+1<visible_count {selected+=1;} continue; }
                KeyCode::Up | KeyCode::Char('k') => { error_msg=None; pending_d=false; pending_g=false; if selected>0 {selected-=1;} continue; }
                KeyCode::Right | KeyCode::Char('l') | KeyCode::PageDown => {
                    error_msg=None; pending_d=false; pending_g=false;
                    if !visible.is_empty() {
                        let cur = visible[selected].0.clone();
                        let mut nxt=selected+1;
                        while nxt<visible_count && visible[nxt].0==cur {nxt+=1;}
                        if nxt<visible_count {selected=nxt;}
                    }
                    continue;
                }
                KeyCode::Left | KeyCode::Char('h') | KeyCode::PageUp => {
                    error_msg=None; pending_d=false; pending_g=false;
                    if !visible.is_empty() && selected>0 {
                        let cur = visible[selected].0.clone();
                        let mut start=selected;
                        while start>0 && visible[start-1].0==cur {start-=1;}
                        if start>0 {
                            let prev = visible[start-1].0.clone();
                            let mut pstart=start-1;
                            while pstart>0 && visible[pstart-1].0==prev {pstart-=1;}
                            selected=pstart;
                        }
                    }
                    continue;
                }
                KeyCode::Home => { error_msg=None; pending_d=false; pending_g=false; selected=0; continue; }
                KeyCode::End => { error_msg=None; pending_d=false; pending_g=false; if visible_count>0 {selected=visible_count-1;} continue; }
                KeyCode::Char('g') => { error_msg=None; if pending_g {selected=0; pending_g=false;} else {pending_g=true; pending_d=false;} continue; }
                KeyCode::Char('G') => { error_msg=None; pending_d=false; pending_g=false; if visible_count>0 {selected=visible_count-1;} continue; }
                KeyCode::Enter => {
                    pending_d=false; pending_g=false;
                    if visible.is_empty() {continue;}
                    let (f, ln, _) = visible[selected].clone();
                    let full = results.iter().find(|r| r.display_path==f).map(|r| r.path.clone()).unwrap_or(f.clone());
                    match open_editor(&full, ln, &editor_choice, &custom_cmd) {
                        Ok(_) => { error_msg=None; }
                        Err(_) => {
                            let ed = editor_choice.clone().unwrap_or("vim".to_string());
                            error_msg=Some(format!("Failed to open editor '{}'. Is it installed?", ed));
                        }
                    }
                    continue;
                }
                KeyCode::Delete => {
                    error_msg=None; pending_d=false; pending_g=false;
                    if !visible.is_empty() { let (f,ln,_) = visible[selected].clone(); filtered.insert((f,ln)); }
                    continue;
                }
                KeyCode::Char('d') => {
                    error_msg=None;
                    if pending_d {
                        if !visible.is_empty() { let (f,ln,_) = visible[selected].clone(); filtered.insert((f,ln)); }
                        pending_d=false;
                    } else { pending_d=true; pending_g=false; }
                    continue;
                }
                KeyCode::Char('w') => {
                    if pending_d {
                        error_msg=None;
                        if !visible.is_empty() {
                            let (f,_,_) = visible[selected].clone();
                            for (ff,ll,_) in visible.clone() { if ff==f { filtered.insert((ff,ll)); } }
                        }
                        pending_d=false;
                    } else { pending_d=false; pending_g=false; }
                    continue;
                }
                KeyCode::Char('v') => { error_msg=None; pending_d=false; pending_g=false; if viewer==ViewerMode::Vertical {viewer=ViewerMode::None;} else {viewer=ViewerMode::Vertical;} continue; }
                KeyCode::Char('s') => { error_msg=None; pending_d=false; pending_g=false; if viewer==ViewerMode::Horizontal {viewer=ViewerMode::None;} else {viewer=ViewerMode::Horizontal;} continue; }
                KeyCode::Char('+') | KeyCode::Char('=') => { viewer_size+=2; continue; }
                KeyCode::Char('-') | KeyCode::Char('_') => { viewer_size-=2; continue; }
                KeyCode::Char('/') => { show_search=true; search_input=pattern.clone(); pending_d=false; pending_g=false; continue; }
                KeyCode::F(5) => { show_search=true; search_input=pattern.clone(); pending_d=false; pending_g=false; continue; }
                KeyCode::Char('n') => { error_msg=None; pending_d=false; pending_g=false; results.sort_by(|a,b| a.display_path.cmp(&b.display_path)); selected=0; continue; }
                KeyCode::Char('m') => { error_msg=None; pending_d=false; pending_g=false; results.sort_by(|a,b| a.modified.cmp(&b.modified)); selected=0; continue; }
                KeyCode::Char('c') => { error_msg=None; pending_d=false; pending_g=false; results.sort_by(|a,b| a.created.cmp(&b.created)); selected=0; continue; }
                KeyCode::Char('a') => { error_msg=None; pending_d=false; pending_g=false; results.sort_by(|a,b| a.accessed.cmp(&b.accessed)); selected=0; continue; }
                _ => { pending_d=false; pending_g=false; continue; }
            }
        } else if let Event::Resize(_,_) = ev { continue; }
    }
    cleanup(&mut out);
    Ok(())
}

fn get_visible(results: &Vec<FileMatches>, filtered: &HashSet<(String, usize)>) -> Vec<(String, usize, String)> {
    let mut v=Vec::new();
    for f in results {
        for (ln, line) in &f.matches {
            if filtered.contains(&(f.display_path.clone(), *ln)) {continue;}
            v.push((f.display_path.clone(), *ln, line.clone()));
        }
    }
    v
}

