        let mut count = 0;
        for ch in content.chars() {
            if count >= w.saturating_sub(2) { break; }
            disp.push(ch);
            count += 1;
        }
        line.push_str(&disp);
        for _ in count..w.saturating_sub(2) { line.push(' '); }
        line.push('│');
        queue!(out, Print(line))?;
    }
    // bottom border
    queue!(out, cursor::MoveTo(x as u16, (y+h-1) as u16))?;
    let mut bot = String::new();
    bot.push('╰');
    for _ in 0..w.saturating_sub(2) { bot.push('─'); }
    bot.push('╯');
    queue!(out, Print(bot))?;
    Ok(())
}

