fn draw_box_plain(out: &mut std::io::Stdout, x: usize, y: usize, w: usize, h: usize, lines: &Vec<DL>) -> anyhow::Result<()> {
    use crossterm::{cursor, queue, style::Print};
    if w < 2 || h < 2 { return Ok(()); }
    // top border
    queue!(out, cursor::MoveTo(x as u16, y as u16))?;
    let mut top = String::new();
    top.push('╭');
    for _ in 0..w.saturating_sub(2) { top.push('─'); }
    top.push('╮');
    queue!(out, Print(top))?;
    // content
    for row in 0..h.saturating_sub(2) {
        queue!(out, cursor::MoveTo(x as u16, (y+1+row) as u16))?;
        let mut line = String::new();
        line.push('│');
        let content = if row < lines.len() { lines[row].text.clone() } else { String::new() };
