        ("Shift-g, End", "Jump to the last match"),
        ("Enter", "Open current file"),
        ("dd, Delete", "Filter out selected match"),
        ("dw", "Filter out all matches in current file"),
        ("v", "Toggle vertical context viewer"),
        ("s", "Toggle horizontal context viewer"),
        ("+", "Increase context viewer size"),
        ("-", "Decrease context viewer size"),
        ("F5, /", "Open search pattern popup"),
        ("n", "Sort search results by name"),
        ("m", "Sort search results by time modified"),
        ("c", "Sort search results by time created"),
        ("a", "Sort search results by time accessed"),
        ("", ""),
        ("Press any key to close…", ""),
    ];
    // Popup dimensions: centered, width ~60? From capture, popup width ~60? Let's compute: popup shows "┌──────────────────────── igrep 1.3.0 ────────────────────────┐" 
    // That's 1 + 24 + 12 + 23 +1? Actually title " igrep 1.3.0 " centered. We'll use fixed width 61? Let's measure from capture: popup line length?
    // From s2_9.txt, popup line: "│                           │ Down, j            │ Select next match                      │                            │"
    // That's outer box + popup. Hard.
    // Simpler: popup width 61, height 26? Original popup height? From capture, popup covers ~24 rows (from row 4 to 27?) Let's use width 63, height 26.
    let popup_w = 63;
    let popup_h = 26;
    let start_x = cols.saturating_sub(popup_w)/2 + 10; // offset? Actually centered? In capture, popup is centered horizontally? Let's approximate centered.
    // In capture, popup starts at col ~27? For 120 cols, centered 63 width would start at (120-63)/2=28. Good.
    let sx = cols.saturating_sub(popup_w)/2;
    let sy = rows.saturating_sub(popup_h)/2;
    // Draw border with title "igrep 1.3.0"
    let title = "igrep 1.3.0";
    // top border: ┌ + ─* + title + ─* + ┐
    // Title format: "┌──────────────────────── igrep 1.3.0 ────────────────────────┐" - need to replicate exactly.
    // From capture: "┌──────────────────────── igrep 1.3.0 ────────────────────────┐" length?
    // Let's construct: total width popup_w, title centered with single spaces?
    // We'll do: "┌" + "─".repeat((popup_w-2 - title.len()-2)/2) + " " + title + " " + "─".repeat(remaining) + "┐"
    let inner_w = popup_w.saturating_sub(2);
    let title_with_spaces = format!(" {} ", title);
    let left_dash = (inner_w.saturating_sub(title_with_spaces.len()))/2;
    let right_dash = inner_w.saturating_sub(title_with_spaces.len()).saturating_sub(left_dash);
    let top = format!("┌{}{}{}┐", "─".repeat(left_dash), title_with_spaces, "─".repeat(right_dash));
    queue!(out, cursor::MoveTo(sx as u16, sy as u16))?;
    queue!(out, Print(top))?;
    // content rows: first blank? In capture, after top, next line is "│                                                             │" (blank)
    // Then "│ Key(s)             │ Action                                 │" etc.
    // Actually all_lines includes header. We'll show blank line first, then all_lines scrolled, then blank + "Press..."? No, all_lines already includes Press...
    // The visible window shows ~ (popup_h-2) lines of all_lines starting at scroll?
    // From scroll tests, initial shows header + first items, scrolled shows later items. The popup has fixed height, scroll offset changes which slice is shown.
    // The first line after top is blank? Let's check: s2_0 shows after top: "│                                                             │" (blank), then "│ Key(s) ..."? Actually s2_0 first content after top is blank, then Key(s), then separator, then q... So blank + header.
    // And bottom has blank + "└...┘"? In s2_9, bottom shows "│                                                             │" (blank), "│ Press any key...", "│                                                             │" (blank), "└...┘"
    // So structure: top, blank, [scrollable content], blank? Or content includes blanks?
    // Our all_lines already includes blanks and Press... So we just show slice.
    // But need to handle that top blank and bottom blank are always? Actually all_lines[0] is Key(s), but capture shows blank before Key(s). So there is an extra blank at top not in all_lines? Let's add.
    // For simplicity, we'll construct display list as: blank, then all_lines scrolled, padded with blanks.
    let mut display: Vec<String> = Vec::new();
    display.push(" ".repeat(inner_w)); // blank
    // Add all_lines formatted as " Key(s)             │ Action" etc. Need to format two columns with │ separator?
    // From capture: "│ Key(s)             │ Action                                 │" - that's inside popup: left col width? Let's measure: " Key(s)             │ Action" - left part " Key(s)             " (20?) then "│" then " Action..."?
    // We'll format as: format!(" {:<18}│ {:<37}", left, right) ??? Need to get exact spacing.
    // Let's look at raw: "│ q, Esc, Ctrl+c     │ Quit                                   │"
    // Inside popup, after "│ ", then left col "q, Esc, Ctrl+c     " (19?)? Then "│ " then right "Quit..." padded?
    // To match exactly, we need to replicate spacing. Let's derive from capture:
    // Example line: "│ q, Esc, Ctrl+c     │ Quit                                   │"
    // Remove outer "│ " prefix and " │" suffix? Actually popup line is "│ <content> │" where content width = inner_w (61?).
    // Content is "q, Esc, Ctrl+c     │ Quit                                   " ??? Hmm.
    // Let's instead directly store the exact strings as observed (without outer border), then pad.
    // From capture, inner content for each row (between │ and │) is:
    // For header: " Key(s)             │ Action                                 "
    // For separator: " ───────────────────┼─────────────────────────────────────── "
    // For normal: " q, Esc, Ctrl+c     │ Quit                                   "
    // We need to replicate these exactly, including spaces.
    // Let's hardcode the exact inner strings as per observed (we have them from scroll tests).
    // We'll create a vector of exact inner strings (without outer │).
    let inner_lines = get_keymap_inner();
    // Apply scroll: show slice starting at scroll, height = popup_h-2 (excluding top/bottom borders)
    let visible_h = popup_h.saturating_sub(2);
    for i in 0..visible_h {
        let idx = scroll + i;
        let content = if idx < inner_lines.len() { inner_lines[idx].clone() } else { " ".repeat(inner_w) };
        // Ensure content len == inner_w (pad/truncate)
        let mut c = content.clone();
        // Truncate to inner_w chars (counting chars, not bytes, since ─ is multibyte but single width? For simplicity, use chars)
        let chars: Vec<char> = c.chars().collect();
        if chars.len() > inner_w {
