        } else {
            c = format!("{}{}", c, " ".repeat(inner_w - chars.len()));
        }
        let line = format!("│{}│", c);
        queue!(out, cursor::MoveTo(sx as u16, (sy+1+i) as u16))?;
        queue!(out, Print(line))?;
    }
    // bottom border
    let bot = format!("└{}┘", "─".repeat(inner_w));
    queue!(out, cursor::MoveTo(sx as u16, (sy+popup_h-1) as u16))?;
    queue!(out, Print(bot))?;
    Ok(())
}

